const input = $input.first().json;
const norm = (value) => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLocaleLowerCase('fr-FR').replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
const plans = { companies: [], establishments: [], aliases: [], identity_snapshots: [], job_offer_updates: [] };
for (const env of input.sirene_envelopes || []) {
  for (const c of env.candidates || []) {
    const company_key = c.siren ? `siren:${c.siren}` : null;
    const establishment_key = c.siret ? `siret:${c.siret}` : null;
    if (company_key) plans.companies.push({ company_key, siren: c.siren, legal_name: c.legal_name || null, naf_code: c.naf_code || null, employee_band: c.employee_band || null, identity_confidence: c.identity_confidence || 0, updated_at: input.now_utc });
    if (company_key && establishment_key) plans.establishments.push({ establishment_key, company_key, siren: c.siren, siret: c.siret, legal_name: c.legal_name || null, trade_name: c.trade_name || null, establishment_status: c.establishment_status || null, address_line: c.address_line || null, postal_code: c.postal_code || null, city: c.city || null, identity_confidence: c.identity_confidence || 0, match_rule_version: 'g8n.company-matching.v1', updated_at: input.now_utc });
    for (const alias of [c.legal_name, c.trade_name].filter(Boolean)) plans.aliases.push({ alias_key: `${company_key}:${norm(alias)}`, company_key, alias_type: alias === c.legal_name ? 'legal_name' : 'trade_name', alias_value: alias, normalized_alias: norm(alias), source: 'sirene', updated_at: input.now_utc });
    const entity_key = establishment_key || company_key;
    if (entity_key && c.payload_hash) plans.identity_snapshots.push({ identity_snapshot_key: `sirene:${establishment_key ? 'establishment' : 'company'}:${entity_key}:${c.payload_hash}`, provider: 'sirene', entity_type: establishment_key ? 'establishment' : 'company', entity_key, payload_hash: c.payload_hash, payload_path: c.payload_path || null, source_version: c.source_version || 'unknown', fetched_at: c.fetched_at || input.now_utc, valid_from: c.source_updated_at || c.fetched_at || input.now_utc, valid_to: null, is_current: true, updated_at: input.now_utc });
  }
}
for (const offer of input.matched_offers || []) plans.job_offer_updates.push({ offer_key: offer.offer_key, company_key: offer.company_key, establishment_key: offer.establishment_key, updated_at: input.now_utc });
return [{ json: { ...input, upsert_plans: plans, aggregation_key: 'company_key', next_step: 'Wire local Data Table upserts in transactional order.' } }];
